from pathlib import Path
import json
r=Path(__file__).resolve().parent/'assets-v1';t=json.loads((r/'tokens.json').read_text())
palette=''.join(f'<span><i style="background:{c}"></i>{n.upper()}<small>{c}</small></span>' for n,c in t['theme'].items())
modes=''.join(f'<div><img src="modes/{m}.svg"><b>{n}</b></div>' for m,n in [('trivia','TRIVIA'),('millionaire','MILLIONAIRE'),('imposter','IMPOSTER'),('turf','TURF WAR')])
animals=''.join(f'<div><img src="avatars/{p["animal"]}-badge.svg"><b>{p["slot"]} · {p["animal"].upper()}</b></div>' for p in t['players'])
states=''.join(f'<div><img src="panels/button-{n}.svg"><span>{n.upper()}</span></div>' for n in ['default','focus','pressed','locked','correct','incorrect','disabled'])
s='''<!doctype html><meta charset="utf-8"><title>TriviTV · Asset sheet</title><style>*{box-sizing:border-box}body{margin:0;width:1280px;height:900px;padding:28px 40px;background:linear-gradient(155deg,#b3a1e4,#6f699c 53%,#1b233f);color:#1b233f;font-family:Arial,sans-serif}header{height:90px;display:flex;align-items:center;justify-content:space-between}header img{width:330px}header p{text-align:right;font-size:15px;line-height:1.5;font-weight:bold}.palette{display:flex;gap:12px;padding:12px 18px;background:#f6e7c8;border:3px solid #1b233f;border-radius:16px;box-shadow:0 5px 0 #1b233f}.palette span{flex:1;display:grid;grid-template-columns:35px 1fr;grid-template-rows:1fr 1fr;column-gap:9px;font-size:12px;font-weight:bold;align-items:center}.palette i{width:34px;height:34px;border:2px solid #1b233f;border-radius:8px;grid-row:1/3}.palette small{font-size:10px}.top{display:grid;grid-template-columns:1.1fr 1fr;gap:25px;margin-top:22px;height:330px}.arena{width:100%;height:100%;object-fit:contain}.modes{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:repeat(2,minmax(0,1fr));gap:12px;min-height:0}.arena{min-height:0;max-height:330px}.modes div{background:#f6e7c8;border:3px solid #1b233f;border-radius:18px;box-shadow:0 5px 0 #1b233f;display:flex;align-items:center;justify-content:center;gap:10px}.modes img{width:115px;height:125px;object-fit:contain}.modes b{font-size:13px;width:90px}.animal-row{display:grid;grid-template-columns:repeat(8,1fr);gap:14px}.animal-row div{display:flex;flex-direction:column;align-items:center;gap:9px}.animal-row img{width:90px;height:90px}.animal-row b{font-size:11px;color:#f6e7c8}.states{display:flex;gap:10px}.states div{flex:1;position:relative}.states img{width:100%;height:52px}.states span{position:absolute;inset:13px 0 0;text-align:center;font-size:9px;font-weight:bold;color:#1b233f}.states div:last-child span{color:#f6e7c8}h2{font-size:14px;letter-spacing:1px;color:#f6e7c8;margin:22px 0 12px}footer{margin-top:20px;display:flex;justify-content:space-between;color:#f6e7c8;font-size:12px}.note{color:#f6e7c8;font-size:11px;opacity:.8;margin:9px 0 0}</style><header><img src="brand/wordmark-navy.svg"><p>PLAYFUL ARCADE ASSET PACK · V1<br>Editable SVG · PNG exports · transparent scene art</p></header><div class="palette">PALETTE</div><div class="top"><img class="arena" src="art/party-arena.webp"><div class="modes">MODES</div></div><h2>8 DISTINCT PLAYER IDENTITIES · NO FACES</h2><div class="animal-row">ANIMALS</div><h2>BUTTON UI · NAVY OUTLINES · OFFSET DEPTH</h2><div class="states">STATES</div><p class="note">55 editable vector assets + raster exports, five backgrounds, tokens, CSS and interactive preview.</p><footer><span>Based on the supplied screenshot palette and original playful direction.</span><span>TriviTV · 2026</span></footer>'''
for k,v in [('PALETTE',palette),('MODES',modes),('ANIMALS',animals),('STATES',states)]:s=s.replace(k,v)
(r/'asset-sheet.html').write_text(s,encoding='utf8')
